package com.insight.quantlife.tests;
import android.app.*;import android.os.Bundle;import org.json.*;import java.io.*;import com.insight.quantlife.*;
public class ExaUpgradeTest extends Instrumentation {
 int passed;void check(boolean b,String s)throws Exception{if(!b)throw new Exception(s);passed++;Bundle o=new Bundle();o.putString("stream","PASS "+s+"\n");sendStatus(0,o);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();try{ByteArrayOutputStream buffer=new ByteArrayOutputStream();try(InputStream f=getTargetContext().openFileInput("exa-upgrade-snapshot.json")){byte[] b=new byte[4096];int n;while((n=f.read(b))!=-1)buffer.write(b,0,n);}JSONObject snap=new JSONObject(buffer.toString("UTF-8"));MainHost h=new MainHost(this);h.open();JSONObject now=(JSONObject)h.call("init",new JSONObject());for(String field:new String[]{"records","messages","wikiPages"})check(now.get(field).toString().equals(snap.get(field).toString()),"1.4.0 to1.4.1 preserves "+field);JSONObject before=snap.getJSONObject("settings"),after=now.getJSONObject("settings");if(!before.has("linkSearch"))after.remove("linkSearch");check(before.toString().equals(after.toString()),"Existing model/Tavily settings and opt-outs preserved");check(getTargetContext().getSharedPreferences("secure",0).getString("settings","").equals(snap.getString("secureCiphertext")),"Upgrade never rewrites encrypted keys");try(TrackStore db=new TrackStore(getTargetContext())){check(db.gpx("2026-10-17").equals(snap.getString("gpx")),"GPX unchanged by Exa feature");check(db.diagnostics("2026-10-17").getJSONArray("rawPoints").toString().equals(snap.getJSONArray("raw").toString()),"GPS raw data unchanged");}check(!now.has("points")&&!now.has("rawPoints"),"AI initialization excludes GPS");out.putString("stream","PASS: "+passed+" Exa upgrade checks\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("stream","FAIL after "+passed+": "+e);finish(Activity.RESULT_CANCELED,out);}}
}
